package com.contentmover.mobile;
import org.json.JSONObject;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public final class CryptoInterop { public static void main(String[] args)throws Exception {JSONObject vector=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8));byte[] key=Transfer.decode(vector.getString("key"));String plain=vector.getString("plain");if(!plain.equals(Transfer.open(key,vector.getString("sealed"))))throw new Exception("Windows -> Java mismatch");boolean rejected=false;try{Transfer.open(new byte[32],vector.getString("sealed"));}catch(Exception e){rejected=true;}if(!rejected)throw new Exception("wrong key accepted");Files.write(Paths.get(args[1]),Transfer.seal(key,plain).getBytes(StandardCharsets.UTF_8));System.out.println("PASS: Android production crypto interoperates with Windows; wrong-key rejection.");} }
